572	
573	static const pet_behavior_t *pick_from_pool(const pet_behavior_t *pool,
574	                                            int count)
575	{
576	    int total = 0;
577	    for (int i = 0; i < count; i++)
578	        total += pool[i].weight;
579	    if (total <= 0) return &pool[0];
580	
581	    int r = rand() % total;
582	    for (int i = 0; i < count; i++)
583	    {
584	        r -= pool[i].weight;
585	        if (r < 0) return &pool[i];
586	    }
587	    return &pool[count - 1];
588	}
