1489	int dm_pet_create(lv_obj_t *parent)
1490	{
1491	    if (!parent) return -1;
1492	
1493	    if (!g_inited)
1494	    {
1495	        srand((unsigned)time(NULL));
1496	        pet_load();
1497	        g_inited = true;
1498	    }
1499	
1500	    /* 幂等：已创建则只重新停靠/置顶，避免重复 timer 泄漏 */
1501	    if (g_cont && lv_obj_is_valid(g_cont))
1502	    {
1503	        pet_park_bottom_right();
1504	        pet_apply_sprite_scale();
1505	        if (g_anim_timer) lv_timer_resume(g_anim_timer);
1506	        if (g_behavior_timer) lv_timer_resume(g_behavior_timer);
1507	        return 0;
1508	    }
1509	
1510	    /* 容器：右下角（FLOATING 脱离 flex，不挤健康卡）
1511	     * 尺寸收紧：只比宠物大一圈（气泡+名字），减少空白区吞触摸 */
1512	    g_cont = lv_obj_create(parent);
1513	    lv_obj_set_size(g_cont, PET_SIZE + DM(24), PET_SIZE + DM(48));
1514	    lv_obj_set_style_bg_opa(g_cont, LV_OPA_TRANSP, 0);
1515	    lv_obj_set_style_border_width(g_cont, 0, 0);
1516	    lv_obj_set_style_pad_all(g_cont, 0, 0);
1517	    lv_obj_clear_flag(g_cont, LV_OBJ_FLAG_SCROLLABLE);
1518	    lv_obj_add_flag(g_cont, LV_OBJ_FLAG_FLOATING);
1519	    /* 整容器可点：放大命中区；吞 CLICKED 防唤醒 */
1520	    lv_obj_add_flag(g_cont, LV_OBJ_FLAG_CLICKABLE);
1521	    lv_obj_add_event_cb(g_cont, pet_body_press_cb, LV_EVENT_PRESSED, NULL);
1522	    lv_obj_add_event_cb(g_cont, pet_body_pressing_cb, LV_EVENT_PRESSING, NULL);
1523	    lv_obj_add_event_cb(g_cont, pet_body_release_cb, LV_EVENT_RELEASED, NULL);
1524	    lv_obj_add_event_cb(g_cont, pet_consume_click_cb, LV_EVENT_CLICKED, NULL);
1525	    pet_park_bottom_right();
1526	
1527	    /* 身体：lv_image 宠物；scale 按帧 header.w 自适应（猫128/狗24）
1528	     * 不单独 CLICKABLE——命中穿透到 g_cont，避免子/父双触发 */
1529	    g_body = lv_image_create(g_cont);
1530	    lv_obj_set_size(g_body, PET_SIZE, PET_SIZE);
1531	    lv_obj_align(g_body, LV_ALIGN_CENTER, 0, 0);
1532	    lv_obj_add_flag(g_body, LV_OBJ_FLAG_OVERFLOW_VISIBLE);
1533	    lv_obj_remove_flag(g_body, LV_OBJ_FLAG_CLICKABLE);
1534	    if (pet_frames()[g_state].frames[0])
1535	        lv_image_set_src(g_body, pet_frames()[g_state].frames[0]);
1536	    pet_apply_sprite_scale();
1537	
1538	    /* 气泡（紧贴精灵头顶：256px 精灵居中于328px容器，上方留白60px，
1539	     * 气泡在容器顶往下28px处 → 离精灵顶约8px） */
1540	    g_bubble = lv_obj_create(g_cont);
1541	    lv_obj_set_size(g_bubble, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
1542	    lv_obj_align(g_bubble, LV_ALIGN_TOP_MID, 0, DM(14));
1543	    lv_obj_set_style_bg_color(g_bubble, lv_color_hex(0xFFFFFF), 0);
1544	    lv_obj_set_style_bg_opa(g_bubble, LV_OPA_90, 0);
1545	    lv_obj_set_style_radius(g_bubble, DM(10), 0);
1546	    lv_obj_set_style_border_width(g_bubble, 1, 0);
1547	    lv_obj_set_style_border_color(g_bubble, lv_color_hex(0xE0E0E0), 0);
1548	    lv_obj_set_style_pad_hor(g_bubble, DM(8), 0);
1549	    lv_obj_set_style_pad_ver(g_bubble, DM(4), 0);
1550	    lv_obj_add_flag(g_bubble, LV_OBJ_FLAG_HIDDEN);
1551	
1552	    g_bubble_lbl = lv_label_create(g_bubble);
1553	    lv_label_set_text(g_bubble_lbl, "");
1554	    lv_obj_set_style_text_font(g_bubble_lbl, PET_BUBBLE_FONT, 0);
1555	    lv_obj_set_style_text_color(g_bubble_lbl, lv_color_hex(0x333333), 0);
1556	
1557	    /* 初始状态（必须在 timer 之前） */
1558	    g_state = pet_next_state();
1559	    pet_select_behavior();
1560	    pet_apply_sprite_scale();
1561	    if (pet_frames()[g_state].frames[0])
1562	        lv_image_set_src(g_body, pet_frames()[g_state].frames[0]);
1563	
1564	    /* Timer 创建 */
1565	    g_anim_timer       = lv_timer_create(pet_anim_cb, PET_ANIM_TICK_MS, NULL);
1566	    g_behavior_timer   = lv_timer_create(pet_behavior_cb, PET_BEHAVIOR_TICK_MS, NULL);
1567	    g_save_timer       = lv_timer_create(pet_save_cb, PET_SAVE_INTERVAL_S * 1000, NULL);
1568	    g_poll_timer       = lv_timer_create(pet_poll_cb, 100, NULL);
1569	    g_time_timer       = lv_timer_create(pet_time_cb, PET_TIME_TICK_MS, NULL);
1570	
1571	    LV_LOG_USER("[pet] created: %s (type=%d) state=%s mood=%d/%d/%d",
1572	                g_pet.name, g_pet.pet_type, dm_pet_state_name(g_state),
1573	                g_pet.attrs.hunger, g_pet.attrs.happiness, g_pet.attrs.energy);
1574	
1575	    /* 长离线欢迎气泡 */
1576	    if (g_welcome_back_pending) {
1577	        g_welcome_back_pending = false;
1578	        if (g_bubble && g_bubble_lbl) {
1579	            lv_label_set_text(g_bubble_lbl, "想你啦，主人~");
1580	            lv_obj_clear_flag(g_bubble, LV_OBJ_FLAG_HIDDEN);
1581	            g_bubble_ticks = PET_BUBBLE_DURATION_TICKS * 2;
1582	        }
1583	    }
1584	
1585	    return 0;
1586	}
